import get from 'lodash/get';
import { EMPTY_OBJECT, SchemaRendererMode } from '../constants';
export const getRenderKit = ({ config, schema, }) => {
    const entityType = get(schema, 'entityParameters.type');
    const controlType = get(schema, 'entityParameters.controlType');
    const ControlComponent = get(config, `${entityType}.controls.${controlType}.Component`);
    const controlProps = get(schema, 'entityParameters.controlProps') || EMPTY_OBJECT;
    const controlIndependent = get(config, `${entityType}.controls.${controlType}.independent`);
    const controlWrapperType = get(schema, 'entityParameters.controlWrapperType');
    const ControlWrapperComponent = get(config, `${entityType}.wrappers.${controlWrapperType}`);
    const controlWrapperProps = get(schema, 'entityParameters.controlWrapperProps') || EMPTY_OBJECT;
    const viewType = get(schema, 'entityParameters.viewType');
    const ViewComponent = get(config, `${entityType}.views.${viewType}`);
    const viewProps = get(schema, 'entityParameters.viewProps') || EMPTY_OBJECT;
    const viewIndependent = get(config, `${entityType}.views.${viewType}.independent`);
    const viewWrapperType = get(schema, 'entityParameters.viewWrapperType');
    const ViewWrapperComponent = get(config, `${entityType}.wrappers.${viewWrapperType}`);
    const viewWrapperProps = get(schema, 'entityParameters.viewWrapperProps') || EMPTY_OBJECT;
    return {
        [SchemaRendererMode.Form]: {
            Component: ControlComponent,
            props: controlProps,
            independent: controlIndependent,
            Wrapper: ControlWrapperComponent,
            wrapperProps: controlWrapperProps,
        },
        [SchemaRendererMode.Overview]: {
            Component: ViewComponent,
            props: viewProps,
            independent: viewIndependent,
            Wrapper: ViewWrapperComponent,
            wrapperProps: viewWrapperProps,
        },
    };
};
